def comb2 (n : Int) : Int :=
  n * (n - 1) / 2

def ValidInput (n m : Int) : Prop :=
  1 ≤ m ∧ m ≤ n

def MinFriendshipPairs (n m : Int) : Int :=
  let k := n / m
  let p := n % m
  p * comb2 (k + 1) + (m - p) * comb2 k

def MaxFriendshipPairs (n m : Int) : Int :=
  comb2 (n - m + 1)

@[reducible, simp]
def solve_precond (n m : Int) : Prop :=
  ValidInput n m
